/**
 * Textarea: a multi-line text field.
 * Purpose: long text such as messages and descriptions. Generated by shadcn, then re-themed to Grove.
 *   Owner: design system.
 * Props: invalid (sets aria-invalid), autoGrow (the box grows with the text, up to a limit, in
 *   browsers that support field-sizing; others keep a fixed box), counter (already-formatted text
 *   such as "120 / 500", shown below and announced politely), every native textarea prop.
 * Responsive: full width; at least 128 px tall; the reader can resize it vertically.
 * Accessibility: as Input. The counter is a polite live region, so it does not interrupt typing.
 * States: default, hover, focus, error, disabled, read-only.
 * Dependencies: cn. Tests: inputs.test.tsx; Design Lab "Fields" (S2-T07).
 * UX reference: ds-components, Fields (c-core.css .textarea).
 */
import type { ComponentProps, ReactNode } from "react";
import { cn } from "@/lib/cn";

type TextareaProps = Omit<ComponentProps<"textarea">, "ref"> & {
  invalid?: boolean;
  autoGrow?: boolean;
  counter?: ReactNode;
};

function Textarea({ className, invalid, autoGrow = false, counter, ...props }: TextareaProps) {
  const field = (
    <textarea
      data-slot="textarea"
      aria-invalid={invalid || props["aria-invalid"]}
      className={cn(
        "min-h-32 w-full min-w-0 resize-y rounded-md border-[length:var(--bw-field)] border-line-input bg-surface px-4 py-3",
        "text-body font-medium text-ink placeholder:font-normal placeholder:text-subtle",
        "transition-colors duration-(--dur-fast) hover:border-primary",
        "focus-visible:border-primary focus-visible:outline-2 focus-visible:outline-offset-1",
        "aria-invalid:border-[length:var(--bw-error)] aria-invalid:border-danger",
        "read-only:border-line-strong read-only:bg-canvas-sunken read-only:text-muted",
        "disabled:cursor-not-allowed disabled:border-line-strong disabled:bg-canvas-sunken disabled:text-muted",
        autoGrow && "max-h-96 field-sizing-content",
        className,
      )}
      {...props}
    />
  );
  if (counter === undefined) return field;
  return (
    <div className="w-full" data-slot="textarea-wrap">
      {field}
      <p aria-live="polite" className="mt-1 text-right text-caption text-muted">
        {counter}
      </p>
    </div>
  );
}

export { Textarea };
